import {afterEach,describe,it,expect} from 'vitest';
import {render,screen,cleanup} from '@testing-library/react';
import TrainingEvaluation from './TrainingEvaluation';
import {decode,type Comparison} from './api';
// Actual saved server response, generated by verification; not a live mock rate card.
import evidence from './test-fixtures/training-evaluation.response.json';
afterEach(cleanup);
describe('Model evaluation evidence',()=>{
  it('renders real verified API metrics including an accuracy trade-off',()=>{
    const data=decode(evidence);render(<TrainingEvaluation data={data}/>);
    expect(screen.getByText('Training quality, not just an accuracy number')).toBeInTheDocument();
    expect(screen.getByText(/v3 test 93.47% → v3.1 93.19% \(-0.28 percentage points\)/)).toBeInTheDocument();
    expect(screen.getByText('TN 421')).toBeInTheDocument();expect(screen.getAllByText('FN 17')).toHaveLength(2);
    expect(screen.getByText(/holdout was previously inspected/)).toBeInTheDocument();
    expect(screen.getAllByText('94.91%').length).toBeGreaterThan(0);
  });
  it('renders nothing when the API has no evaluation evidence',()=>{
    const data=structuredClone(evidence) as unknown as Comparison;delete data.alternative.model_trace!.evaluation;
    const {container}=render(<TrainingEvaluation data={data}/>);expect(container).toBeEmptyDOMElement();
  });
  it('rejects invalid evaluation metrics instead of showing fictional numbers',()=>{
    const data=structuredClone(evidence);data.alternative.model_trace.evaluation.targets.Budget_Overrun.test.xgboost.accuracy=NaN;
    expect(()=>decode(data)).toThrow('Invalid training evaluation metrics');
  });
  it('keeps selected model features distinct from the full planning record',()=>{
    const data=decode(evidence),trace=data.alternative.model_trace!;
    expect(Object.keys(trace.input_features!)).toHaveLength(26);
    expect(trace.model_features!.Budget_Overrun).toEqual(['Planned_Budget_Utilization']);
    expect(trace.evaluation!.test_used_for_selection).toBe(false);
  });
});
